import Input from "../../components/Input";
import "./Colors.css";

function Colors({ handleChange }) {
  return (
    <div>
      <h2 className="sidebar-title color-title">Colors</h2>

      <label className="sidebar-label-container">
        <input onChange={handleChange} type="radio" value="" name="test2" />
        <span className="checkmark all"></span>
        All
      </label>

      <label className="sidebar-label-container">
        <input
          onChange={handleChange}
          type="radio"
          value="black"
          title="Black"
          name="test1"
          color="black"
        />
        <span className="checkmark" style={{ background: "black" }}></span>
        Black
      </label>

      <label className="sidebar-label-container">
        <input
          onChange={handleChange}
          type="radio"
          value="blue"
          title="Blue"
          name="test1"
          color="blue"
        />
        <span className="checkmark" style={{ background: "blue" }}></span>
        Blue
      </label>

      <label className="sidebar-label-container">
        <input
          onChange={handleChange}
          type="radio"
          value="red"
          title="Red"
          name="test1"
          color="red"
        />
        <span className="checkmark" style={{ background: "red" }}></span>
        Red
      </label>

      <label className="sidebar-label-container">
        <input
          onChange={handleChange}
          type="radio"
          value="green"
          title="Green"
          name="test1"
          color="green"
        />
        <span className="checkmark" style={{ background: "green" }}></span>
        Green
      </label>

      <label className="sidebar-label-container">
        <input
          onChange={handleChange}
          type="radio"
          value="white"
          title="White"
          name="test1"
          color="white"
        />
        <span
          className="checkmark"
          style={{ background: "white", border: "2px solid black" }}
        ></span>
        White
      </label>
    </div>
  );
}
export default Colors;
