import img1 from "../assets/proImg1.png";
import img2 from "../assets/proImg2.png";
import img3 from "../assets/proImg3.png";
import "./ProductSection.css";

function ProductSection() {
  const products = [
    {
      id: 1,
      name: "Pencil Eyeliner",
      price: 66,
      rating: 5,
      colors: ["red", "blue", "black"],
      image: img1,
    },
    {
      id: 2,
      name: "Moisturising Cream",
      price: 45,
      rating: 5,
      sale: true,
      colors: ["pink", "red", "gold"],
      image: img2,
    },
    {
      id: 3,
      name: "Cologne Spray",
      price: 48,
      oldPrice: 60,
      rating: 0,
      colors: ["pink", "orange", "red"],
      image: img3,
    },
  ];

  return (
    <section className="text-center product-collection">
      <div className="container">
        <div className="section-header center mb-5">
          <div className="sub-title">THE LATEST</div>
          <h2 className="title">Latest Products</h2>
        </div>

        <div className="row g-4">
          {products.map((product) => (
            <div className="col-md-4" key={product.id}>
              <div className="card border-0 position-relative h-100 product-card">
                {product.sale && (
                  <span className="badge bg-success position-absolute top-0 end-0 m-3 pt-1 rounded-pill">
                    Sale
                  </span>
                )}

                <div className="card-body">
                  <img
                    src={product.image}
                    alt={product.name}
                    className="mb-3 product-img"
                    style={{ width: 250 }}
                  />

                  <div className="mb-2">
                    {"★★★★★".split("").map((star, i) => (
                      <span
                        key={i}
                        style={{
                          color: i < product.rating ? "#ffc107" : "#ddd",
                          fontSize: 18,
                        }}
                      >
                        ★
                      </span>
                    ))}
                  </div>

                  <h6 className="fw-semibold">{product.name}</h6>

                  <p className="fw-bold mb-2">
                    {product.oldPrice && (
                      <span className="text-muted text-decoration-line-through me-2">
                        ${product.oldPrice}
                      </span>
                    )}
                    ${product.price}
                  </p>

                  <div>
                    {product.colors.map((c, i) => (
                      <span
                        key={i}
                        className="color-dot"
                        style={{ background: c }}
                      />
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        <button className="slider-btn btn mt-5">VIEW ALL</button>
      </div>
    </section>
  );
}

export default ProductSection;
