import mail_icon from "../assets/mail_icon.png";
import apple_logo from "../assets/Apple_Pay.svg";
import google_pay from "../assets/Google_Pay.svg";
import visa_logo from "../assets/Visa_Inc.svg";
import mastercard from "../assets/Mastercard.svg";
import "./Footer.css";

function Footer() {
  return (
    <>
      <footer className="footer-section">
        <div className="container">
          <div className="row">
            {/* Location */}
            <div className="col-md-3">
              <div className="contact-info">
                <div className="contact-info-inner">
                  <ul>
                    <li className="address"><i class="fa-solid fa-location-dot"></i>
                    <div className="content-title"><h5 style={{ marginBottom: "5px" }}>Location</h5>
                    <p>B-982 New Dehli <br /> India</p>
                    </div>
                    </li>

                    <li className="address"><i class="fa-solid fa-phone"></i>
                    <div className="content-title"><h5 className="mt-3 mb-1">Contact Us</h5>
                    <p><a href="tel: +91 11 1111 1111">+91 11 1111 1111</a></p>
                    </div>
                    </li>

                    <li className="address"><i class="fa-solid fa-envelope"></i>
                    <div className="content-title"><h5 className="mt-3 mb-0">Email</h5>
                    <p><a href="mailto: info@gmail.com">info@gmail.com</a></p>
                    </div>
                    </li>
                  </ul>
              </div>
              </div>
            </div>

            {/* Your Account */}
            <div className="col-md-2">
              <h5>Your Account</h5>
              <ul className="footer-list">
                <li><a href="#">Personal Info</a></li>
                <li><a href="#">Orders</a></li>
                <li><a href="#">Credit Slips</a></li>
                <li><a href="#">Addresses</a></li>
                <li><a href="#">My Wishlists</a></li>
              </ul>
            </div>

            {/* Our Company */}
            <div className="col-md-2">
              <h5>Our Company</h5>
              <ul className="footer-list">
                <li><a href="#">Legal Notice</a></li>
                <li><a href="#">Secure Payment</a></li>
                <li><a href="#">Contact Us</a></li>
                <li><a href="#">Sitemap</a></li>
                <li><a href="#">My Account</a></li>
              </ul>
            </div>

            {/* Product */}
            <div className="col-md-2">
              <h5>Product</h5>
              <ul className="footer-list">
                <li><a href="#">Delivery</a></li>
                <li><a href="#">Price Drop</a></li>
                <li><a href="#">New Product</a></li>
                <li><a href="#">Best Product</a></li>
                <li><a href="#">Stores</a></li>
              </ul>
            </div>

            <div className="col-md-3">
              <div className="newsletter_icon center">
                <img src={mail_icon} alt="mail_icon" />
                <h2 className="center" style={{ fontSize: "24px" }}>
                  Newsletter
                </h2>
              </div>

              <div className="footer-social center">
                <ul className="footer-social-list">
                  <li className="social-item facebook">
                    <a href="#" className="social-link">
                      <i class="fa-brands fa-facebook-f"></i>
                    </a>
                  </li>
                  <li className="social-item instagram">
                    <a href="#" className="social-link">
                      <i class="fa-brands fa-instagram"></i>
                    </a>
                  </li>
                  <li className="social-item snapchat">
                    <a href="#" className="social-link">
                      <i class="fa-brands fa-snapchat"></i>
                    </a>
                  </li>
                  <li className="social-item vimeo">
                    <a href="#" className="social-link">
                      <i class="fa-brands fa-vimeo-v"></i>
                    </a>
                  </li>
                </ul>
              </div>

              <form>
                <div className="newsletter-box">
                  <input type="email" placeholder="Your email" />
                  <button>➤</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </footer>

      <div className="footer-bottom">
        <div class="container">
          <div class="row align-items-center">
            <div class="footer-left col-lg-6 col-md-12 col-sm-12">
              <div class="footer__copyright">© 2026, All rights reserved.</div>
            </div>

            <div class="footer-right col-lg-6 col-md-12 col-sm-12">
              <div class="payment-icons">
                <ul class="list list-payment">
                  <li className="payment-item">
                    <img src={apple_logo} alt="apple logo" title="Apple Pay" />
                  </li>
                  <li className="payment-item">
                    <img
                      src={google_pay}
                      alt="googlePay logo"
                      title="Google Pay"
                    />
                  </li>
                  <li className="payment-item">
                    <img src={visa_logo} alt="visa logo" title="Visa" />
                  </li>
                  <li className="payment-item">
                    <img src={mastercard} alt="mastercard" title="Mastercard" />
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Footer;
