import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Navigation } from "swiper/modules";

import "swiper/css";
import "swiper/css/navigation";

import categry_img_1 from "../assets/product-1.png";
import categry_img_2 from "../assets/product-2.png";
import categry_img_3 from "../assets/product-3.png";
import categry_img_4 from "../assets/product-4.png";
import categry_img_5 from "../assets/product-5.png";
import categry_img_6 from "../assets/product-6.png";
import categry_img_7 from "../assets/product-7.png";

import "./SubCategory.css";

const categories = [
  { img: categry_img_1, name: "Trending Watch", bg: "#98c7cb" },
  { img: categry_img_2, name: "Men's T-Shirt", bg: "#efd5cc" },
  { img: categry_img_3, name: "Laptops", bg: "#566675" },
  { img: categry_img_5, name: "Men's T-Shirt", bg: "#efd5cc" },
  { img: categry_img_4, name: "Headphones", bg: "#b1b3c7" },
  { img: categry_img_6, name: "Fitness Bands", bg: "#98c7cb" },
  { img: categry_img_7, name: "Android Phones", bg: "#efd5cc" },
];

const SubCategory = () => {
  return (
    <section className="sub-category">
      <div className="container">

        <div className="section-header center mb-5">
          <div className="sub-title">THE PRODUCTS</div>
          <h2 className="recommended-title title center">
            Shop by Categories
          </h2>
        </div>

        <Swiper
          modules={[Autoplay, Navigation]}
          spaceBetween={20}
          slidesPerView={7}
          loop={true}
          navigation={true}
          autoplay={{
            delay: 3000,
            disableOnInteraction: false
          }}
          breakpoints={{
            320: { slidesPerView: 2 },
            576: { slidesPerView: 3 },
            768: { slidesPerView: 4 },
            1024: { slidesPerView: 5 }
          }}
        >
          {categories.map((item, index) => (
            <SwiperSlide key={index}>
              <div className="category_column">
                <div className="element-image-txt">

                  <figure
                    className="category-data"
                    style={{ background: item.bg }}
                  >
                    <a href="#" className="anchor-link">
                      <picture>
                        <img src={item.img} alt={item.name} />
                      </picture>
                    </a>
                  </figure>

                  <div className="image-text">
                    <p>{item.name}</p>
                  </div>

                </div>
              </div>
            </SwiperSlide>
          ))}

        </Swiper>

      </div>
    </section>
  );
};

export default SubCategory;