import { useState } from "react";
import "../Recommended/Recommended.css";
import "../Products/Products.css";
import Category from "../Sidebar/Category/Category";
import Price from "../Sidebar/Price/Price";
import Colors from "../Sidebar/Colors/Colors";
import "../Sidebar/Sidebar.css";

function Recommended({ handleClick, result, handleChange }) {
  const [activeBtn, setActiveBtn] = useState("");

  const buttons = [
    { label: "All Products", value: "" },
    { label: "Nike", value: "Nike" },
    { label: "Adidas", value: "Adidas" },
    { label: "Puma", value: "Puma" },
    { label: "Vans", value: "Vans" },
  ];

  const handleBtnClick = (value) => {
    setActiveBtn(value);

    handleClick({
      target: { value: value },
    });
  };

  return (
    <div className="recommended-section">
      <div className="container">
        <div className="section-header center mb-5">
          <div className="sub-title">THE PRODUCTS</div>
          <h2 className="recommended-title title center">Recommended</h2>
        </div>

        {/* Brand Buttons */}

        <div className="recommended-flex">
          {buttons.map((btn, index) => (
            <button
              key={index}
              className={`btns ${activeBtn === btn.value ? "active-btn" : ""}`}
              onClick={() => handleBtnClick(btn.value)}
            >
              {btn.label}
            </button>
          ))}
        </div>

        <div className="row">
          {/* Sidebar */}

          <div className="col-lg-3 col-md-6">
            <section className="sidebar">
              <Category handleChange={handleChange} />
              <Price handleChange={handleChange} />
              <Colors handleChange={handleChange} />
            </section>
          </div>

          {/* Products */}

          <div className="col-lg-9 col-md-6">
            <section className="products-section">
              <div className="card-container">{result}</div>
            </section>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Recommended;
