import React, { useEffect, useState } from "react";
import { HiMiniBars3BottomRight } from "react-icons/hi2";
import { FiSearch, FiUser, FiShoppingCart, FiX } from "react-icons/fi";
import logo from "../assets/e-logo.svg";
import "./Navbar.css";

const Header = () => {
  const [isSticky, setIsSticky] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [userModal, setUserModal] = useState(false);
  const [isLogin, setIsLogin] = useState(true);

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.pageYOffset > 60);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      {/* HEADER */}
      <header className={`header ${isSticky ? "sticky" : ""}`}>
        <div className="header__row">

          {/* LOGO */}
          <div className="logo">
            <a href="#"><img src={logo} alt="logo" /></a>
          </div>

          {/* DESKTOP NAV */}
          <nav className="nav-desktop">
            <a href="#">Home</a>
            <a href="#">About</a>
            <a href="#">Services</a>
            <a href="#">Contact</a>
          </nav>

          {/* ICONS */}
          <div className="nav-icons">
            <FiSearch onClick={() => setSearchOpen(!searchOpen)} />
            <FiUser onClick={() => setUserModal(true)} />
            <FiShoppingCart />
          </div>

          {/* HAMBURGER */}
          <div className="hamburger" onClick={() => setMenuOpen(true)}>
            <HiMiniBars3BottomRight />
          </div>

        </div>
      </header>

      {/* SEARCH */}
      <div className={`search-box ${searchOpen ? "active" : ""}`}>
        <input type="text" placeholder="Search products..." />
      </div>

      {/* OVERLAY */}
      <div
        className={`overlay ${menuOpen ? "show" : ""}`}
        onClick={() => setMenuOpen(false)}
      ></div>

      {/* SIDE MENU */}
      <div className={`side-menu ${menuOpen ? "open" : ""}`}>

        {/* CLOSE BUTTON */}
        <FiX className="menu-close" onClick={() => setMenuOpen(false)} />

        <a href="#" onClick={() => setMenuOpen(false)}>Home</a>
        <a href="#" onClick={() => setMenuOpen(false)}>About</a>
        <a href="#" onClick={() => setMenuOpen(false)}>Services</a>
        <a href="#" onClick={() => setMenuOpen(false)}>Contact</a>

      </div>

      {/* LOGIN MODAL */}
      {userModal && (
        <div className="user-modal">
          <div className="modal-box">

            <FiX className="close-btn" onClick={() => setUserModal(false)} />

            {isLogin ? (
              <>
                <h2>Login</h2>
                <input type="email" placeholder="Email" />
                <input type="password" placeholder="Password" />
                <button className="btn">Login</button>

                <p>
                  Don't have an account?{" "}
                  <span onClick={() => setIsLogin(false)}>Sign Up</span>
                </p>
              </>
            ) : (
              <>
                <h2>Sign Up</h2>
                <input type="text" placeholder="Name" />
                <input type="email" placeholder="Email" />
                <input type="password" placeholder="Password" />
                <button className="btn">Register</button>

                <p>
                  Already have an account?{" "}
                  <span onClick={() => setIsLogin(true)}>Login</span>
                </p>
              </>
            )}

          </div>
        </div>
      )}
    </>
  );
};

export default Header;